# ================= KAIVAA — Script autonome (sans import) =================
# Objectif : produire df conforme au gabarit
#  - Dates : datetime64[ns]
#  - Texte : object
#  - Numériques : float64 (ou int) reconnus comme "number" par la validation

# ---------- Helpers ----------
def _norm_text(s):
    if s is None:
        return ""
    s = str(s).strip().lower().replace("_", " ").replace("-", " ")
    return " ".join(s.split())

def _find_col(df_, aliases):
    cols = list(df_.columns)
    # exact
    for a in aliases:
        if a in cols:
            return a
    # insensitive
    lower_map = {c.lower(): c for c in cols}
    for a in aliases:
        la = a.lower()
        if la in lower_map:
            return lower_map[la]
    # normalized
    norm_map = {_norm_text(c): c for c in cols}
    for a in aliases:
        na = _norm_text(a)
        if na in norm_map:
            return norm_map[na]
    return None

def _to_datetime64(s):
    """
    Convertit en datetime64[ns] (sans passer par des objets date).
    1) tentative astype('datetime64[ns]')
    2) sinon -> string, remplace '/', tronque à 10 chars -> astype
    """
    try:
        ser = s.astype("datetime64[ns]")
        if str(ser.dtype).lower().startswith("datetime64"):
            return ser
    except Exception:
        pass
    try:
        ser2 = s.astype("string").str.replace("/", "-", regex=False).str.slice(0, 10)
        ser2 = ser2.astype("datetime64[ns]")
        return ser2
    except Exception:
        return s  # fallback (laissera la validation signaler)

def _to_float(s):
    try:
        return s.astype("float64")
    except Exception:
        _nan = float("nan")
        def _try_float(x):
            try:
                return float(x)
            except _:
                return _nan
        return s.map(lambda x: _nan if x is None or (isinstance(x, str) and not x.strip()) else _try_float(x)).astype("float64")

def _to_text_object(s):
    """
    Force un dtype 'object' avec des str Python (pas 'string' pandas).
    """
    try:
        return s.astype("object").map(lambda x: "" if x is None else str(x))
    except Exception:
        return s.map(lambda x: "" if x is None else str(x)).astype("object")

def _const_text_object(df_, value):
    # Serie longueur n au dtype object
    try:
        return df_.index.to_series().map(lambda _: value).astype("object")
    except Exception:
        return df_[:0].assign(_tmp=value).reindex(df_.index)["_tmp"].astype("object")

# ---------- Schéma cible ----------
TARGET_COLS = [
    "Date_début","Date_fin","Année_N",
    "Enseigne","Géographie","Région","Concurrence",
    "Famille","Segment","Groupe","Marque",
    "Product","Produit_détaillé","Unité_volume",
    "Chiffre_d_affaires","Distribution_numérique","Prix_moyen","Volume",
    "Distributeur","Canal"
]

# ---------- Détection colonnes d'entrée ----------
col_start   = _find_col(df, ["Start week week","Start week","Date début","Date_debut","Date start","start"])
col_end     = _find_col(df, ["End week","Date fin","Date_fin","Date end","end"])
col_brand   = _find_col(df, ["Brand","Groupe"])  # ✅ MODIFIÉ : Brand sera utilisé pour Marque
col_subbr   = _find_col(df, ["SubBrand","Marque"])
col_metier  = _find_col(df, ["Metier","Métier","Famille"])
col_submet  = _find_col(df, ["SubMetier","SousMetier","Segment"])
col_pname   = _find_col(df, ["Product name","Produit","Produit_détaillé","Product"])
col_units   = _find_col(df, ["Units","Unités"])
col_volsold = _find_col(df, ["Volume sold","Volume"])
col_liters  = _find_col(df, ["Liters sold","Litres"])
col_dn      = _find_col(df, ["DN","Distribution numérique","Distribution_numérique"])
col_pu      = _find_col(df, ["Prix moyen","Prix_moyen"])
col_ca      = _find_col(df, ["CA","Chiffre d'affaires","Chiffre_d_affaires"])
col_dist    = _find_col(df, ["Distributeur","Enseigne"])
col_canal   = _find_col(df, ["Canal","Channel"])
col_fin     = _find_col(df, ["Finance code","Code produit","SKU"])
col_axe     = _find_col(df, ["Axe"])

# ---------- Copie de travail ----------
df = df.copy()

# 1) Dates (début / fin) — en datetime64[ns]
if col_start is None and col_end is None:
    raise ValueError("Impossible de trouver des dates (début/fin). Vérifie 'Start week week' / 'End week'.")

df["Date_début"] = _to_datetime64(df[col_start]) if col_start else _to_datetime64(df[col_end])
df["Date_fin"]   = _to_datetime64(df[col_end])   if col_end   else df["Date_début"]

# 2) Année_N (texte / object) basé sur Date_début (fenêtres ~12 mois)
if str(df["Date_début"].dtype).lower().startswith("datetime64"):
    max_start = df["Date_début"].max()
    diffs_days = (max_start - df["Date_début"]).dt.days.astype("float64")

    def _label(v):
        if v != v:  # NaN
            return ""
        k = int(max(0.0, v // 365.0))
        return "Ancien" if k >= 5 else ("N" if k == 0 else f"N-{k}")

    df["Année_N"] = diffs_days.map(_label).astype("object")
else:
    df["Année_N"] = _const_text_object(df, "")

# 3) Dimensions (texte → dtype object)
df["Distributeur"] = _to_text_object(df[col_dist]) if col_dist else _const_text_object(df, "")
df["Canal"]        = _to_text_object(df[col_canal]) if col_canal else _const_text_object(df, "")

df["Enseigne"]    = df["Distributeur"]                     # même valeur
df["Géographie"]  = _const_text_object(df, "France")
df["Région"]      = _const_text_object(df, "France")
df["Concurrence"] = _const_text_object(df, "Entreprise")

df["Famille"] = _to_text_object(df[col_metier]) if col_metier else _const_text_object(df, "")
df["Segment"] = _to_text_object(df[col_submet]) if col_submet else _const_text_object(df, "")

# ✅ MODIFICATION : Groupe fixé à "L'Oréal", Marque provient de "Brand"
df["Groupe"]  = _const_text_object(df, "L'Oréal")  # ✅ Toujours "L'Oréal"
df["Marque"]  = _to_text_object(df[col_brand])  if col_brand  else _const_text_object(df, "")  # ✅ Utilise Brand

# Produit / Produit_détaillé = Product name
prod_series = _to_text_object(df[col_pname]) if col_pname else _const_text_object(df, "")
df["Product"]          = prod_series
df["Produit_détaillé"] = prod_series

# 4) Volume + Unité_volume (numériques en float64)
if col_liters and df[col_liters].notna().any():
    df["Volume"] = _to_float(df[col_liters])
    df["Unité_volume"] = _const_text_object(df, "Litres")
elif col_volsold and df[col_volsold].notna().any():
    df["Volume"] = _to_float(df[col_volsold])
    df["Unité_volume"] = _const_text_object(df, "Unités")
elif col_units:
    df["Volume"] = _to_float(df[col_units])
    df["Unité_volume"] = _const_text_object(df, "Unités")
else:
    df["Volume"] = _to_float(df.assign(_v=float("nan"))["_v"])
    df["Unité_volume"] = _const_text_object(df, "Unités")

# 5) KPIs (numériques)
df["Distribution_numérique"] = _to_float(df[col_dn]) if col_dn else _to_float(df.assign(_v=float("nan"))["_v"])
df["Prix_moyen"]             = _to_float(df[col_pu]) if col_pu else _to_float(df.assign(_v=float("nan"))["_v"])
df["Chiffre_d_affaires"]     = _to_float(df[col_ca]) if col_ca else _to_float(df.assign(_v=float("nan"))["_v"])

# 6) Colonnes inutiles à retirer (si présentes)
to_drop = []
for c in [col_fin, col_axe, "Finance code", "Axe"]:
    if c and c in df.columns and c not in TARGET_COLS:
        to_drop.append(c)
if to_drop:
    df = df.drop(columns=to_drop, errors="ignore")

# 7) Garantir toutes les colonnes cibles & réordonner (en gardant les bons dtypes)
for c in TARGET_COLS:
    if c not in df.columns:
        if c in ("Date_début", "Date_fin"):
            df[c] = _to_datetime64(_const_text_object(df, ""))  # restera NaT en datetime64[ns]
        elif c in ("Chiffre_d_affaires","Distribution_numérique","Prix_moyen","Volume"):
            df[c] = _to_float(df.assign(_v=float("nan"))["_v"])
        else:
            df[c] = _const_text_object(df, "")
df = df[TARGET_COLS]

# 8) Tri optionnel (du plus récent au plus ancien si Date_fin en datetime64)
try:
    if str(df["Date_fin"].dtype).lower().startswith("datetime64"):
        df = df.sort_values(
            ["Date_fin","Distributeur","Canal","Groupe","Marque","Product"],
            ascending=[False, True, True, True, True, True]
        ).reset_index(drop=True)
except Exception:
    pass

# ================= FIN ============================================================
